export interface TeamCatalogPlayer {
  number: number;
  name: string;
  position: string;
  age?: number;
  club?: string;
  imageUrl?: string;
}

export interface TeamCatalogEntry {
  code: string;
  countryName: string;
  iso2: string;
  sourceLabel: string;
  sourceUrl: string;
  players: TeamCatalogPlayer[];
}

const fifaImage = (path: string) =>
  `https://digitalhub.fifa.com/transform/${path}?io=transform:fill,aspectratio:1x1,width:320,gravity:top&quality=75`;
const fifaSquad = (slug: string) =>
  `https://www.fifa.com/pt/tournaments/mens/worldcup/canadamexicousa2026/teams/${slug}/squad`;
const officialSquadLabel = 'Elenco atualizado a partir da lista oficial da FIFA.';

